/**
 * Tree.Node: one item of the tree: its row and, when it is an open branch, the rows under it.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, type JSX } from 'solid-js'

import { Each, Icon, claimSlot, createDerived, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/tree.module.css'
import Spinner from './Spinner'
import type { TreeItem, TreeMessages } from './Tree'

export interface TreeNodeProps {
  item: TreeItem
  /**
   * The level it sits at: 0 at the top.
   */
  level: number
  /**
   * The open branches by id.
   */
  open: ReadonlySet<string>
  /**
   * The selected item's id.
   */
  selected: string | null
  messages: TreeMessages
}

/** Tree.Node: one item of the tree: its row and, when it is an open branch, the rows under it. */
export default function TreeNode(given: TreeNodeProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const uid = createUniqueId()
    const under = createDerived(() => props.item.children ?? [])
    const branch = createDerived(() => under.value.length > 0 || props.item.hasChildren === true)
    const disabled = createDerived(() => props.item.disabled === true)
    const expanded = createDerived(
      () => branch.value && !disabled.value && props.open.has(props.item.id),
    )
    const loading = createDerived(() => props.item.loading === true)
    const hasMore = createDerived(() => props.item.hasMore === true)
    const chosen = createDerived(() => !disabled.value && props.selected === props.item.id)
    return (
      <li
        class={styles.item}
        role="treeitem"
        aria-labelledby={`${uid}-label`}
        aria-describedby={props.item.description === undefined ? undefined : `${uid}-description`}
        aria-expanded={branch.value ? expanded.value : undefined}
        aria-selected={disabled.value ? undefined : chosen.value}
        aria-disabled={disabled.value ? true : undefined}
        aria-busy={expanded.value && loading.value ? true : undefined}
        data-tree-item={props.item.id}
        data-selected={chosen.value ? '' : undefined}
        data-disabled={disabled.value ? '' : undefined}
      >
        {/* row */}
        <div class={styles.row} style={{ '--pm-tree-level': props.level }} data-tree-part="row">
          {branch.value ? (
            <span class={styles.toggle} data-tree-part="toggle" aria-hidden="true">
              <span class={styles.chevron}>
                <Icon name="next" size="sm" />
              </span>
            </span>
          ) : (
            <span class={styles.slot} />
          )}
          <span class={styles.text}>
            {/* label */}
            <span class={styles.label} id={`${uid}-label`}>
              {props.item.label}
            </span>
            {props.item.description !== undefined ? (
              <span class={styles.description} id={`${uid}-description`}>
                {props.item.description}
              </span>
            ) : null}
          </span>
        </div>
        {expanded.value && (under.value.length > 0 || loading.value || hasMore.value) ? (
          <ul class={styles.group} role="group">
            <Each of={under.value} by={(child) => child.id} renew>
              {(child) => (
                <TreeNode
                  item={child}
                  level={props.level + 1}
                  open={props.open}
                  selected={props.selected}
                  messages={props.messages}
                />
              )}
            </Each>
            {hasMore.value ? (
              <li
                class={styles.item}
                role="treeitem"
                aria-labelledby={`${uid}-more`}
                aria-selected="false"
                aria-busy={loading.value ? true : undefined}
                data-tree-part="more"
              >
                <div
                  class={styles.row}
                  style={{ '--pm-tree-level': props.level + 1 }}
                  data-tree-part="row"
                  data-busy={loading.value ? '' : undefined}
                >
                  <span class={styles.slot}>
                    {loading.value ? <Spinner size="sm" label={props.messages.loading} /> : null}
                  </span>
                  <span class={styles.text}>
                    <span class={styles.more} id={`${uid}-more`}>
                      {loading.value ? props.messages.loading : props.messages.loadMore}
                    </span>
                  </span>
                </div>
              </li>
            ) : loading.value ? (
              <li class={styles.item} role="none">
                <div
                  class={styles.row}
                  style={{ '--pm-tree-level': props.level + 1 }}
                  data-busy={''}
                >
                  <span class={styles.slot}>
                    <Spinner size="sm" label={props.messages.loading} />
                  </span>
                  <span class={styles.text}>
                    <span class={styles.status} aria-hidden="true">
                      {props.messages.loading}
                    </span>
                  </span>
                </div>
              </li>
            ) : null}
          </ul>
        ) : null}
      </li>
    )
  })
}
